import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Events API","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/forge/events.md","filePath":"en/modules/forge/events.md","lastUpdated":0}`),a={name:`en/modules/forge/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="events-api" tabindex="-1">Events API <a class="header-anchor" href="#events-api" aria-label="Permalink to “Events API”">​</a></h1><p>Forge events live in <code>emaki.jiuwu.craft.forge.api.event</code>. Both are synchronous Bukkit events fired on the forging player&#39;s owner thread, and both the GUI forge path and the public <code>ForgeOperations.forgeAsync</code> share the same event contract.</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Thread</th><th>Cancellable</th><th>Mutable field</th><th>Cancellation / outcome</th><th>Runtime paths</th></tr></thead><tbody><tr><td><code>ForgeStartEvent</code></td><td>After validation and the prepared forge complete, just before asynchronous execution and material commit</td><td>Player owner thread</td><td>Yes</td><td><code>successRate</code>; finite values clamp to 0–100, non-finite values become 0</td><td>Cancelling stops the attempt without scheduling execution and without consuming materials; the API returns <code>CANCELLED</code></td><td>GUI confirmation and <code>forgeAsync</code></td></tr><tr><td><code>ForgeCompletedEvent</code></td><td>After a forge result has been resolved, for both successful and resolvable failed attempts</td><td>Player owner thread</td><td>No</td><td>None</td><td>Post notification, cannot be rolled back</td><td>GUI completion and <code>forgeAsync</code> completion</td></tr></tbody></table><p><code>ForgeStartEvent</code> exposes the player, recipe id, and first-craft flag as read-only values. <code>ForgeCompletedEvent</code> exposes success, result item, quality, and multiplier as read-only values; on failure the result item and quality may be empty.</p><p>When owner or generation validation fails before the start, no start event is fired. During completion, if the player&#39;s owner scheduling has already retired, the result is still mapped and settled but the completed event can be skipped. A cancelled start produces no completed event. Catalog validation, opening the GUI or recipe book, and refreshing items are not themselves forge attempts.</p>`,5)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};